      "@id": "entity:source-meet_peri.step.5.desc",
      "@type": "prov:Entity",
      "prov:value": "Peri asks what this means for a new situation. Knowledge becomes portable."
    },
    {
      "@id": "entity:target-meet_peri.step.5.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "تسأل بيري عن معنى هذا في حالة جديدة. يصبح المعرفة محمولة.",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.5.desc-2026-07-07T20:33:09.629325+00:00"
