    {
      "@id": "activity:translation-meet_peri.exchange.1.text-2026-07-07T20:33:09.629325+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-07T20:33:09.629325+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.exchange.1.text",
      "@type": "prov:Entity",
      "prov:value": "You\\'re at the creek bank. Before we measure anything — what\\'s the first thing you notice about the water right here versus ten feet upstream?"
    },
    {
      "@id": "entity:target-meet_peri.exchange.1.text-v1",
      "@type": "prov:Entity",
      "prov:value": "أنت على شاطئ Stream. قبل أن نقيس أي شيء - ما هو أول شيء تلاحظه حول الماء هنا مقابل عشر أقدام في اتجاه مجرى النهر؟",
      "generated_by": {
        "@id": "activity:translation-meet_peri.exchange.1.text-2026-07-07T20:33:09.629325+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.exchange.1.text"
      }
    },
    {
      "@id": "activity:translation-meet_peri.exchange.2.text-2026-07-07T20:33:09.629325+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-07T20:33:09.629325+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.exchange.2.text",
      "@type": "prov:Entity",
      "prov:value": "It\\'s slower here and there\\'s more mud on the bottom."
    },
    {
      "@id": "entity:target-meet_peri.exchange.2.text-v1",
      "@type": "prov:Entity",
      "prov:value": "هو أبطأ هنا وهناك يوجد أكثر من الطين في القاع.",
      "generated_by": {
        "@id": "activity:translation-meet_peri.exchange.2.text-2026-07-07T20:33:09.629325+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.exchange.2.text"
      }
    },
    {
      "@id": "activity:translation-meet_peri.exchange.3.text-2026-07-07T20:33:31.634128+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-07T20:33:31.634128+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.exchange.3.text",
      "@type": "prov:Entity",
      "prov:value": "Good observation. Why do you think the mud settled here and not upstream where the water is faster?"
    },
    {
      "@id": "entity:target-meet_peri.exchange.3.text-v1",
      "@type": "prov:Entity",
      "prov:value": "جيد الملاحظة. لماذا تظن أن الطين استقرت هنا وليس في أعلى النهر حيث الماء أسرع؟",
      "generated_by": {
        "@id": "activity:translation-meet_peri.exchange.3.text-2026-07-07T20:33:31.634128+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.exchange.3.text"
      }
    },
    {
      "@id": "activity:translation-meet_peri.exchange.4.text-2026-07-07T20:33:31.634128+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-07T20:33:31.634128+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.exchange.4.text",
      "@type": "prov:Entity",
      "prov:value": "Maybe slower water can\\'t carry as much stuff?"
    },
    {
      "@id": "entity:target-meet_peri.exchange.4.text-v1",
      "@type": "prov:Entity",
      "prov:value": "ربما الماء البطيء لا يمكن أن يحمل الكثير من الأشياء؟",
      "generated_by": {
        "@id": "activity:translation-meet_peri.exchange.4.text-2026-07-07T20:33:31.634128+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.exchange.4.text"
      }
    },
    {
      "@id": "activity:translation-meet_peri.exchange.5.text-2026-07-07T20:33:31.634128+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-07T20:33:31.634128+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.exchange.5.text",
      "@type": "prov:Entity",
      "prov:value": "That\\'s the right direction. What could you measure or photograph here to support that idea?"
    },
    {
      "@id": "entity:target-meet_peri.exchange.5.text-v1",
      "@type": "prov:Entity",
      "prov:value": "هذا الاتجاه الصحيح. ما الذي يمكن قياسه أو تصويره هنا لدعم هذا الإيديا؟",
      "generated_by": {
        "@id": "activity:translation-meet_peri.exchange.5.text-2026-07-07T20:33:31.634128+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.exchange.5.text"
      }
    },
