    {
      "@id": "activity:translation-field_journal_desc-2026-07-07T21:13:47.904765+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-07T21:13:47.904765+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-field_journal_desc",
      "@type": "prov:Entity",
      "prov:value": "Students don't just do an activity — they record it. The Field Journal is where raw observations become structured knowledge. Back at their desk, students expand their notes with extended analysis, personal reflection, and connections to what they already know. Teachers can review, respond, and promote entries to the student's permanent portfolio."
    },
    {
      "@id": "entity:target-field_journal_desc-v1",
      "@type": "prov:Entity",
      "prov:value": "الطلاب لا يقتصرون على القيام بمهمة - بل يسجلونها. هو المكان الذي يتحول فيه الملاحظات الخام إلى معارف منظمة. عند العودة إلى مكتبهم، يوسع الطلاب ملاحظاتهم بتمديد التحليل الشخصي والتحليل الممتد وتحديد الصلة بما يعرفونه بالفعل. يمكن للمدرسين مراجعة الإجابات وتطويرها ونقلها إلى ملف الطالب الدائم.",
      "generated_by": {
        "@id": "activity:translation-field_journal_desc-2026-07-07T21:13:47.904765+00:00"
      },
      "used_source": {
        "@id": "entity:source-field_journal_desc"
      }
    },
