    {
      "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware began as a white paper written inside McGraw-Hill Education. It argued that GPS-enabled mobile devices would transform learning — that students walking through real places, guided by structured inquiry, could learn in a way textbooks never allowed."
    },
    {
      "@id": "entity:target-components_landingpage.peripateticware_began_as_a_white_paper_w-v1",
      "@type": "prov:Entity",
      "prov:value": "بدأ \"Peripateticware\" كمقترح مكتوب داخل شركة \"McGraw-Hill Education\". وقد أيد أن الأجهزة المحمولة المسموح بها GPS ستتحول إلى التعلم - حيث يمكن للطلاب الذين يسيرون في أماكن حقيقية، مدعومين بالتحقيقات المنظمة، تعلم بطريقة لم يسمح بها الكتب المدرسية.",
      "generated_by": {
        "@id": "activity:translation-components_landingpage.peripateticware_began_as_a_white_paper_w-2026-07-07T21:21:41.014146+00:00"
